package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type Product struct {
	ID          int     `json:"id"`
	Name        string  `json:"name"`
	Category    string  `json:"category"`
	Price       float64 `json:"price"`
	Description string  `json:"description"`
	SKU         string  `json:"sku"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	if connStr == "" {
		connStr = "postgres://catalog_app:s3cr3t@db:5432/products?sslmode=disable"
	}
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchProducts handles full-text product search with optional filters
func searchProducts(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	maxPrice := r.URL.Query().Get("max_price")
	sortBy := r.URL.Query().Get("sort")

	// Build query with filters
	baseQuery := "SELECT id, name, category, price, description, sku FROM products WHERE 1=1"
	var conditions []string

	if category != "" {
		conditions = append(conditions, fmt.Sprintf(" AND category = '%s'", category))
	}
	if minPrice != "" {
		conditions = append(conditions, fmt.Sprintf(" AND price >= %s", minPrice))
	}
	if maxPrice != "" {
		conditions = append(conditions, fmt.Sprintf(" AND price <= %s", maxPrice))
	}

	fullQuery := baseQuery + strings.Join(conditions, "")

	// Apply sorting - validated against allowlist
	validSorts := map[string]string{
		"price_asc": "price ASC", "price_desc": "price DESC",
		"name": "name ASC", "newest": "id DESC",
	}
	if s, ok := validSorts[sortBy]; ok {
		fullQuery += " ORDER BY " + s
	} else {
		fullQuery += " ORDER BY id ASC"
	}

	fullQuery += " LIMIT 50"

	rows, err := db.Query(fullQuery)
	if err != nil {
		log.Printf("Query error: %v | query: %s", err, fullQuery)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Category, &p.Price, &p.Description, &p.SKU); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

// getProduct retrieves a single product by ID (uses parameterized query)
func getProduct(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Query().Get("id")
	var p Product
	err := db.QueryRow("SELECT id, name, category, price, description, sku FROM products WHERE id = $1", id).Scan(
		&p.ID, &p.Name, &p.Category, &p.Price, &p.Description, &p.SKU)
	if err != nil {
		http.Error(w, "Product not found", 404)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(p)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/api/products/get", getProduct)
	http.HandleFunc("/health", healthCheck)
	log.Println("Catalog service starting on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
